export class Order {
  private constructor(
    readonly id: OrderId, readonly customer: CustomerId, readonly lines: Line[],
  ) {}

  static open(customer: CustomerId, lines: Line[]): Result<Order, OrderError> {
    if (lines.length === 0) return err({ kind: 'EmptyOrder' });
    return ok(new Order(OrderId.generate(), customer, [...lines]));
  }
}

