export function parseOrder(input: unknown): Result<Order, OrderError> {
  const raw = OrderInput.parse(input);            // validate the untrusted shape first
  if (raw.lines.length === 0) return err({ kind: 'EmptyOrder' });
  return ok({ id: orderId(raw.id), customer: raw.customer, lines: raw.lines });
}
